            Reject("unknown attr",Root(Types[i],"Unknown='1'",""));Reject("foreign attr",Root(Types[i],"xmlns:q='urn:q' q:TypeId='1'",""));Reject("unknown child",Root(Types[i],"","<Unknown/>"));Reject("root text",Root(Types[i],"","payload"));Reject("foreign child",Root(Types[i],"","<ObjectMapping xmlns='urn:q'/>"));
