        AssetBuffer absent=Test("ABI/absentFilter",Root(Settings,"","<ObjectMapping/>"),p);Check(Word(absent.InstanceData,24,big)==0,"absent filter does not apply defaults");
        AssetBuffer complete=Test("ABI/full",Root(Settings,"DefaultHealthBar='H\\9'","<ObjectMapping HealthBar='H\\1'><ObjectFilter Rule='ANY' Relationship='ALLIES ENEMIES' Alignment='GOOD' Include='INFANTRY VEHICLE' Exclude='STRUCTURE' StatusBitFlags='STEALTHED' StatusBitFlagsExclude='UNDER_CONSTRUCTION'><ExcludeThing>Object_C</ExcludeThing><IncludeThing>Object_A</IncludeThing><IncludeThing>Object_B</IncludeThing></ObjectFilter></ObjectMapping>"),p);
        Check(complete.InstanceData.Length==200&&Word(complete.InstanceData,4,big)==10&&Word(complete.InstanceData,16,big)==2,"root and mapping refs; total allocation");
        Check(Word(complete.InstanceData,24,big)==2&&Word(complete.InstanceData,28,big)==3&&Word(complete.InstanceData,32,big)==2,"inline ObjectFilter rule relationship alignment");Check(Word(complete.InstanceData,36,big)==1024&&Word(complete.InstanceData,60,big)==4096&&Word(complete.InstanceData,72,big)==512,"KindOf 9-word include/exclude offsets");
        Check(Word(complete.InstanceData,108,big)==132&&Word(complete.InstanceData,112,big)==160&&Word(complete.InstanceData,132,big)==131072&&Word(complete.InstanceData,160,big)==4,"nullable 28-byte status blocks and bits");
        Check(Word(complete.InstanceData,116,big)==2&&Word(complete.InstanceData,120,big)==188&&Word(complete.InstanceData,124,big)==1&&Word(complete.InstanceData,128,big)==196,"thing list counts/order after statuses");
        Offsets(complete.RelocationData,new uint[]{12,108,112,120,128},big,"root pointer then mapping owner pointers by targetblock");Offsets(complete.ImportsData,new uint[]{4,16},big,"imports owner root then mapping");
        foreach(string attr in new[]{"Include","Exclude"})foreach(string name in KindNames){TestDoc("kind/"+attr+"/"+name,FilterAttr(attr,name),p);TestDoc("kind-NUL/"+attr,FilterAttr(attr,name+"\0tail"),p);TestDoc("kind-signs/"+attr,FilterAttr(attr,"+"+name+" -"+name+" -"+name),p);}
